  insert into public.projects (id, user_id, name, description, project_type, status, start_date, end_date, tags, outcomes, reflection) values
    ('00000000-0000-4000-8000-000000000017', uid, '成都博物馆《观妙入真——永乐宫的建筑艺术与传承》特展讲解', '参与成都博物馆特展《观妙入真——永乐宫的建筑艺术与传承》现场讲解服务，负责面向散客及团体观众开展展览讲解，讲解内容涵盖永乐宫历史、建筑营造、元代建筑艺术、斗拱演变、壁画艺术与道教文化；同时参与讲解服务介绍推广、设备管理与团体接待。讲解统计（场次、人次等）待工作结束后补充。', '工作', '进行中', '2026-07-06', '2026-12-06', array['博物馆','特展讲解','永乐宫','古建筑'], array[]::text[], '第一段专业博物馆特展职业讲解经历，对知识储备、体力、声音控制与现场应变的要求远高于校园讲解，正在持续优化讲解词与互动方式。'),
    ('00000000-0000-4000-8000-000000000001', uid, '2026年成都市旅游景区讲解员大赛（优秀奖）', '参加「展都市圈魅力画卷 彰显景区讲解风范」成都市旅游景区讲解员大赛，独立完成内容策划、讲解词撰写与打磨、现场展示，获优秀奖。比赛正式名称、主办单位及级别以获奖证书为准。', '比赛', '已完成', '2026-08-01', null, array['讲解','比赛','景区','表达'], array['优秀奖','最终讲解稿','比赛展示 PPT'], '敢于在更大的舞台表达，比赛经历是个人讲解能力的展示成果。'),
    ('00000000-0000-4000-8000-000000000003', uid, '个人职业经历数据库网站（人生档案馆）', '针对个人经历分散、简历版本混乱的问题，主动设计并开发个人职业经历数据库网站：统一管理教育、工作、校园、项目、科研、荣誉、技能与量化成果，接入 AI 读取岗位需求并自动筛选相关经历生成针对性简历。技术栈 HTML/CSS/原生 JS + Supabase，部署于 GitHub Pages。', '项目', '进行中', '2026-09-07', null, array['网站','知识管理','数字化','AI'], array['完整可用的网站','AI 文件/日记分析','简历导出','数据库设计'], '从 0 到 1 独立完成一个全栈网站，理解了「经历数据库 → AI 筛选 → 生成简历」的产品设计理念。'),
    ('00000000-0000-4000-8000-000000000018', uid, '博物馆讲解服务数据管理系统', '博物馆讲解团队日常需统计值班人员、讲解场次、接待人数、售票数量、收入与提成分配，传统人工统计繁琐且历史数据难查询。主动提出并搭建在线数据管理网站：使用 HTML/CSS/JavaScript + Supabase 实现多人数据同步，使用 Chart.js 实现数据可视化，已实现值班管理、场次记录、收入与提成自动计算，部分功能持续规划迭代中。', '项目', '进行中', '2026-06-01', null, array['网站','数据管理','工作流数字化','AI辅助开发'], array['在线数据管理网站','多人数据同步','收入/提成自动计算','数据图表可视化'], '从真实工作问题出发（人工统计 → 在线记录 → 自动计算 → 可视化），探索用数字化工具优化小型团队日常数据管理。'),
    ('00000000-0000-4000-8000-000000000019', uid, '西南交大校史馆讲解知识库网站', '校史馆讲解团长期积累大量讲解词、人物资料、建筑资料与图片资料，Word 文档查找困难、内容分散、新讲解员学习效率低。正在搭建线上校史讲解知识库：规划校史时间线、展厅分类、完整讲解词、重点人物与建筑、搜索功能，将讲解内容数字化、结构化，服务新讲解员培训与内容更新。', '项目', '进行中', '2026-08-01', null, array['网站','知识管理','校史','数字化培训'], array[]::text[], '将个人讲解经验和校史资料数字化沉淀，探索「文化传播 + 知识管理 + 数字化工具」的结合。'),
    ('00000000-0000-4000-8000-000000000020', uid, '赴上海寻访杨杏佛烈士主题社会实践', '担任西南交通大学档案馆（校史馆）赴上海寻访杨杏佛烈士主题实践队队长，带领4名队员完成3天上海实地寻访（主题“学英雄 学模范——寻访交大英烈”）：实地走访杨杏佛故居、后期居所、遇害地，参观上海铁路博物馆与宋庆龄陵园，完成现场讲解、影像采集与史料核对，为校史馆英烈主题讲解积累一手资料。', '活动', '已完成', '2026-08-01', '2026-08-03', array['社会实践','校史研究','红色文化','寻访'], array['现场照片资料','视频资料','文字记录','社会实践报告'], '档案提供事实依据、遗迹提供空间感受、纪念场所提供传播平台，三者结合才能完整理解历史人物。'),
    ('00000000-0000-4000-8000-000000000014', uid, '校级SRTP科研项目（三星堆文化法语译介）', '课题《法语翻译导游视阈下三星堆文化在法语世界的译介与传播》，核心成员兼主要答辩人。部分成员赴法交流期间，独立承担项目中期答辩与结项答辩，向评审组展示研究逻辑、阶段性成果与创新点。', '项目', '已完成', '2025-05-01', '2026-05-31', array['科研','法语','三星堆','跨文化传播'], array['项目已结项','独立完成中期与结项两次关键答辩'], '独立承担关键答辩锻炼了科研表达与临场应对能力。'),
    ('00000000-0000-4000-8000-000000000010', uid, '作业帮教育科技（成都）·助教', '负责线下班级教学辅助与学生服务：作业批改、学情分析、错题整理、一对一复习辅导、学习社群维护与课后教学复盘。每周跟班3–4个班级，维护10+个学习社群（覆盖200+学生）。', '工作', '已完成', '2025-09-01', '2026-02-28', array['助教','教学辅助','社群运营'], array['授课250+小时','辅导学生1000+人次','6条优化建议被采纳'], '把学生共性问题反馈主讲教师并推动教学调整，理解了教学服务闭环。'),
    ('00000000-0000-4000-8000-000000000015', uid, '雨花敬老院志愿服务', '参与雨花敬老院“无条件敬老”志愿服务，负责长者礼仪接待、用餐秩序维护与协助老人就餐。', '活动', '已完成', '2025-08-01', '2025-08-31', array['志愿服务','敬老'], array[]::text[], ''),
    ('00000000-0000-4000-8000-000000000009', uid, 'TLScontact中智签证·法国签证专员', '参与法国申根签证申请业务全流程：签证材料审核、法语原始文件处理、信息核对、系统录入、生物信息采集与签证制作贴附，熟悉法国使领馆签证规范及标准化业务流程。', '工作', '已完成', '2025-07-01', '2025-09-30', array['签证','法语','审核','涉外'], array['审核1200+份签证材料','完成2000+份签证贴附','零操作失误'], '高重复性涉外工作锻炼了细节管理与高准确率执行。'),
    ('00000000-0000-4000-8000-000000000007', uid, '西南交大校史馆讲解团', '担任西南交通大学校史馆讲解团团长，负责讲解团日常管理及讲解工作：校史讲解、新讲解员培训、团队排班、讲解员考核、重要来访接待、讲解词修订与讲解路线优化。曾为院士、校领导、校党委书记及政府来访人员提供专场讲解。', '工作', '进行中', '2024-10-01', null, array['讲解','团队管理','培训','接待'], array['累计讲解50+场','服务观众800+人次','培训新讲解员20+人'], '从讲解员到团队管理者，学会了用制度（排班、考核）保障接待质量。'),
    ('00000000-0000-4000-8000-000000000016', uid, '暑期三下乡养老院志愿服务', '前往养老院开展慰问服务，负责文艺表演、漆扇制作协助、老人互动与陪伴交流。', '活动', '已完成', '2024-09-01', '2024-09-02', array['志愿服务','三下乡','敬老'], array[]::text[], ''),
    ('00000000-0000-4000-8000-000000000008', uid, '西南交大体育健康超市·太极助教', '连续三个学期担任太极拳课程助教，协助课程教学、系统教授24式简化太极拳、指导学生动作、协助课堂组织与人员管理；负责学院太极比赛集训及带队，获评校级“优秀助教”。', '工作', '已完成', '2024-06-01', '2025-09-30', array['教学','太极','助教','带队'], array['累计教学3000+人次','校级优秀助教','带队连续两年获校级太极比赛团体第一名'], '大规模课堂教学练就了组织协调与带队能力。'),
    ('00000000-0000-4000-8000-000000000011', uid, '中国联通郫都分公司·线上运营与销售', '参与高校新生电话卡推广，主导创建并运营500+人新生线上社群（套餐攻略、产品介绍、在线答疑），沉淀300+意向客户；开学后转入线下推广，累计开卡100+张，获当季中国联通西南交大站代理商销冠。', '工作', '已完成', '2024-06-01', '2024-09-30', array['社群运营','私域','销售'], array['运营500+人新生社群','线上转化90+人','线下开卡100+张','当季代理商销冠（西南交大站）'], '完整跑通「获客→社群运营→私域沉淀→用户转化→线下销售」闭环。'),
    ('00000000-0000-4000-8000-000000000013', uid, '班级公众号与视频号运营', '担任班级宣传委员，独立负责班级微信公众号及视频号运营，完成选题策划、内容撰写、图文编辑、视频拍摄剪辑到发布的全流程。', '活动', '进行中', '2023-10-01', null, array['公众号','视频号','内容运营'], array['发布13篇原创内容','5篇被学院官方平台转载'], ''),
    ('00000000-0000-4000-8000-000000000012', uid, '西南交大外国语学院新语传媒中心', '担任新媒体编辑部干事，参与学院新媒体平台内容运营：公众号内容编辑、图文排版、推送发布、配图设计与内容审核，单篇阅读量稳定1000+。', '活动', '已完成', '2023-09-01', '2024-06-30', array['新媒体','公众号','排版'], array['发布15+篇原创内容','单篇最高阅读量5000+','学院优秀部员'], '')
