-- =====================================================================
-- 李杨个人职业经历数据库 —— 数据录入脚本
--
-- 使用方法：打开 Supabase 控制台 → SQL Editor → 粘贴本文件全部内容 → Run。
-- 前提：请先用邮箱 2052710271@qq.com 在网站上注册/登录一次（系统会自动创建 users 行）。
-- 幂等：可重复执行；重复执行会把这 16 个项目及其挂载内容重置为脚本内容。
-- 注意：只影响下方列出的项目 ID，不会动你在网站上自行新建的其他项目。
-- =====================================================================

do $$
declare
  uid uuid;
begin
  select id into uid from public.users where email = '2052710271@qq.com';
  if uid is null then
    raise exception '未找到该邮箱用户：请先在网站上用 2052710271@qq.com 登录一次，再执行本脚本';
  end if;

  -- ---------- 0. 个人资料 ----------
  update public.users
     set display_name = '李杨', phone = '15680821489', city = '成都',
         job_title = '讲解员 / 内容策划', bio = '博物馆讲解员 · 记录成长'
   where id = uid;

  -- ---------- 0.1 删除旧的不准确比赛项目 ----------
  delete from public.projects
   where user_id = uid and (name like '全国高校大学生场馆讲解风采展示%' or name like '2026年高校讲解比赛%' or name = '个人数字档案馆');

  -- ---------- 1. 项目（16 个） ----------
  on conflict (id) do update set
    user_id = excluded.user_id,
    name = excluded.name,
    description = excluded.description,
    project_type = excluded.project_type,
    status = excluded.status,
    start_date = excluded.start_date,
    end_date = excluded.end_date,
    tags = excluded.tags,
    outcomes = excluded.outcomes,
    reflection = excluded.reflection;

  -- ---------- 2. 角色 ----------
  delete from public.project_roles
   where project_id in ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000015','00000000-0000-4000-8000-000000000016','00000000-0000-4000-8000-000000000017','00000000-0000-4000-8000-000000000018','00000000-0000-4000-8000-000000000019','00000000-0000-4000-8000-000000000020');


  -- ---------- 3. 贡献 ----------
  delete from public.contributions
   where project_id in ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000015','00000000-0000-4000-8000-000000000016','00000000-0000-4000-8000-000000000017','00000000-0000-4000-8000-000000000018','00000000-0000-4000-8000-000000000019','00000000-0000-4000-8000-000000000020');


  -- ---------- 4. 能力证据 ----------
  delete from public.skill_evidence
   where project_id in ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000007','00000000-0000-4000-8000-000000000008','00000000-0000-4000-8000-000000000009','00000000-0000-4000-8000-000000000010','00000000-0000-4000-8000-000000000011','00000000-0000-4000-8000-000000000012','00000000-0000-4000-8000-000000000013','00000000-0000-4000-8000-000000000014','00000000-0000-4000-8000-000000000015','00000000-0000-4000-8000-000000000016','00000000-0000-4000-8000-000000000017','00000000-0000-4000-8000-000000000018','00000000-0000-4000-8000-000000000019','00000000-0000-4000-8000-000000000020');


  -- ---------- 5. 反思 ----------
  delete from public.reflections
   where project_id in ('00000000-0000-4000-8000-000000000001','00000000-0000-4000-8000-000000000003','00000000-0000-4000-8000-000000000017','00000000-0000-4000-8000-000000000020');


  -- ---------- 6. 文件 ----------
  on conflict (id) do update set
    user_id = excluded.user_id,
    project_id = excluded.project_id,
    file_name = excluded.file_name,
    file_type = excluded.file_type,
    file_size = excluded.file_size,
    description = excluded.description,
    importance = excluded.importance,
    tags = excluded.tags,
    uploaded_at = excluded.uploaded_at;

  raise notice '完成：16 个项目及角色/贡献/证据/反思/文件已录入（用户 %）', uid;
end $$;
